"use strict";exports.id=217,exports.ids=[217],exports.modules={4278:(a,i,s)=>{s.d(i,{XL:()=>l,jP:()=>n});let l=[{id:"professionalnaya-uborka",img:"/images/service-apartment.webp",translations:{ru:{title:"Профессиональная уборка в Ташкенте",category:"Помещения",shortDesc:"Регулярная и разовая уборка жилых и коммерческих помещений.",fullDesc:"Мы предоставляем профессиональные услуги уборки квартир, домов и офисов. Наши специалисты используют премиальную гипоаллергенную химию и оборудование Karcher, чтобы ваше пространство сияло чистотой. Работаем быстро, качественно и с гарантией результата.",includes:["Удаление пыли и грязи","Влажная и сухая уборка","Чистка санузлов","Вынос мусора"],price:"от 25.000 за 1 Кв М",metaTitle:"Уборка квартир и офисов в Ташкенте — GrandClean",metaDesc:"Профессиональная уборка квартир, домов и офисов в Ташкенте. Оборудование Karcher, гипоаллергенная химия. Цена от 25 000 за м\xb2. Звоните: +998 93 571 21 51."},uz:{title:"Professional tozalash",category:"Xonalar",shortDesc:"Turar-joy va tijorat binolarini muntazam va bir martalik tozalash.",fullDesc:"Kvartira, uy va ofislarni professional tozalash xizmatlarini ko'rsatamiz. Mutaxassislarimiz premium gipoallergen kimyo va Karcher jihozlaridan foydalanadi. Tez, sifatli va kafolat bilan ishlaymiz.",includes:["Chang va kirlni yo'q qilish","Ho'l va quruq tozalash","Sanitariya tugunini tozalash","Axlatni olib chiqish"],price:"25 000 so'mdan 1 m\xb2 uchun",metaTitle:"Toshkentda kvartira va ofislarni tozalash — GrandClean",metaDesc:"Toshkentda kvartira, uy va ofislarni professional tozalash. Karcher jihozlari, gipoallergen kimyo. Narx 25 000 so'mdan m\xb2. Qo'ng'iroq: +998 93 571 21 51."}},faq:{ru:[{question:"Сколько времени занимает уборка квартиры в Ташкенте?",answer:"Стандартная уборка квартиры площадью 50–70 м\xb2 занимает 2–3 часа. Генеральная уборка той же площади — от 4 до 6 часов."},{question:"Нужно ли предоставлять свою химию и оборудование?",answer:"Нет, GrandClean приедет со всем необходимым: профессиональным оборудованием Karcher и сертифицированными эко-средствами."},{question:"Делаете ли вы уборку после ремонта?",answer:"Да, уборка после ремонта — одна из наших специализаций. Удаляем строительную пыль, цементные разводы, клей с покрытий."},{question:"Гарантируете ли вы качество уборки?",answer:"Да. Если в течение 24 часов после работы вы найдёте недочёты, мы вернёмся и всё исправим бесплатно."}],uz:[{question:"Toshkentda kvartira tozalash qancha vaqt oladi?",answer:"50–70 m\xb2 kvartira standart tozalash 2–3 soat. Bosh tozalash — 4 dan 6 soatgacha."},{question:"O'z kimyoni va jihozlarni taqdim etish kerakmi?",answer:"Yo'q, GrandClean barcha kerakli narsa bilan keladi: Karcher jihozlari va sertifikatlangan eko-vositalar."},{question:"Ta'mirdan keyin tozalash xizmatini ko'rsatasizmi?",answer:"Ha, ta'mirdan keyin tozalash — bizning ixtisoslarimizdan biri. Qurilish changini, tsement izlarini, yapishqoqni olib tashlaymiz."},{question:"Tozalash sifatini kafolatlaysizmi?",answer:"Ha. Ishdan keyin 24 soat ichida kamchilik topilsa, bepul qayta kelib tuzatamiz."}]}},{id:"stirka-kovrov",img:"/images/service-carpet.webp",translations:{ru:{title:"Стирка ковров в Ташкенте",category:"Специальные",shortDesc:"Профессиональная стирка ковров с вывозом и доставкой.",fullDesc:"Фабричная стирка ковров по турецкой технологии. Мы сами заберём ваш ковёр, постираем его с использованием роторных машин и специализированных шампуней, высушим в специальной камере и привезём обратно свежим и чистым.",includes:["Вывоз и бесплатная доставка","Глубокая стирка ротором","Удаление стойких пятен","Сушка в спецкамере"],price:"от 15.000 сум",metaTitle:"Стирка ковров в Ташкенте с доставкой — GrandClean",metaDesc:"Фабричная стирка ковров в Ташкенте по турецкой технологии. Бесплатный вывоз и доставка. Цена от 15 000 сум. ☎ +998 93 571 21 51."},uz:{title:"Gilam yuvish",category:"Maxsus",shortDesc:"Olib ketish va yetkazib berish bilan professional gilam yuvish.",fullDesc:"Turk texnologiyasi bo'yicha fabrika usulida gilam yuvish. Gilamingizni o'zimiz olib ketamiz, rotor mashinalar va maxsus shampunlar bilan yuvik, maxsus kamerada quritib, yangi va toza holda qaytarib olib kelamiz.",includes:["Olib ketish va bepul yetkazib berish","Rotor bilan chuqur yuvish","Qo'shni dog'larni olib tashlash","Maxsus kamerada quritish"],price:"15 000 so'mdan",metaTitle:"Toshkentda gilam yuvish yetkazib berish bilan — GrandClean",metaDesc:"Toshkentda turk texnologiyasi bo'yicha fabrika usulida gilam yuvish. Bepul olib ketish va yetkazib berish. Narx 15 000 so'mdan. ☎ +998 93 571 21 51."}},faq:{ru:[{question:"Как долго стираете ковёр?",answer:"Полный цикл — приемка, стирка, сушка и доставка — занимает от 3 до 5 рабочих дней."},{question:"Выводите ли вы застарелые пятна и запахи?",answer:"Да, используем ферментные шампуни, которые расщепляют пятна от мочи животных, вина, еды."},{question:"Бесплатна ли доставка ковра обратно?",answer:"Вывоз и доставка в пределах Ташкента бесплатны."},{question:"Стираете ли вы ковры из натуральной шерсти и шёлка?",answer:"Да, работаем со всеми видами материалов — синтетика, шерсть, вискоза, шёлк."}],uz:[{question:"Gilamni necha kunda yuvib berasiz?",answer:"To'liq tsikl — qabul, yuvish, quritish va yetkazib berish — 3 dan 5 ish kunigacha davom etadi."},{question:"Eski dog'lar va hidlarni olib tashlaysizmi?",answer:"Ha, hayvon siydigi, vino, oziq-ovqat dog'larini parchalovchi ferment shampunlardan foydalanamiz."},{question:"Gilamni qaytarib yetkazib berish bepulmi?",answer:"Toshkent doirasida olib ketish va yetkazib berish bepul."},{question:"Tabiiy jun va ipak gilamlarni yuvasizmi?",answer:"Ha, barcha turdagi materiallar — sintetika, jun, viskoza, ipak bilan ishlaymiz."}]}},{id:"himchistka-mebeli",img:"/images/service-sofa.webp",translations:{ru:{title:"Химчистка мебели в Ташкенте",category:"Специальные",shortDesc:"Глубокая химчистка диванов, кресел, матрасов и ковров.",fullDesc:"Профессиональная химчистка вернет вашей мебели первоначальный вид. Удаляем сложные пятна, засаленности, запахи домашних животных и пылевых клещей. Используем мощные экстракторы и безопасную химию.",includes:["Диваны и кресла","Матрасы","Ковры и ковролин","Удаление пятен и запахов"],price:"от 50.000 сум",metaTitle:"Химчистка дивана и мебели в Ташкенте — GrandClean",metaDesc:"Профессиональная химчистка диванов, кресел, матрасов в Ташкенте. Удаляем любые пятна и запахи. Цена от 50 000 сум. ☎ +998 93 571 21 51."},uz:{title:"Mebel kimyoviy tozalash",category:"Maxsus",shortDesc:"Divan, kreslo, matras va gilamlarni chuqur kimyoviy tozalash.",fullDesc:"Professional kimyoviy tozalash mebelingizni dastlabki ko'rinishiga qaytaradi. Murakkab dog'lar, yog'li izlar, uy hayvonlari hidlari va chang kanalarini yo'q qilamiz.",includes:["Divan va kreslolar","Matraslar","Gilam va gilamcha","Dog' va hidlarni olib tashlash"],price:"50 000 so'mdan",metaTitle:"Toshkentda divan va mebel kimyoviy tozalash — GrandClean",metaDesc:"Toshkentda divan, kreslo, matraslarni professional kimyoviy tozalash. Har qanday dog' va hidlarni olib tashlaymiz. Narx 50 000 so'mdan. ☎ +998 93 571 21 51."}},faq:{ru:[{question:"Сколько сохнет диван после химчистки?",answer:"В среднем 4–6 часов при хорошей вентиляции."},{question:"Химчистка безопасна для детей и аллергиков?",answer:"Абсолютно. Работаем только с гипоаллергенными препаратами серии Chemspec и HG."},{question:"Можно ли заказать химчистку на дому?",answer:"Да, приезжаем со всем необходимым оборудованием прямо к вам."},{question:"Удалите ли вы запах животных из матраса?",answer:"Да. Используем ферментные нейтрализаторы запаха, которые разрушают молекулы запаха."}],uz:[{question:"Kimyoviy tozalashdan keyin divan qancha qurishadi?",answer:"Yaxshi shamollatilgan xonada o'rtacha 4–6 soat."},{question:"Kimyoviy tozalash bolalar va allergiklar uchun xavfsizmi?",answer:"Mutlaqo. Faqat Chemspec va HG seriyali gipoallergen preparatlar bilan ishlaymiz."},{question:"Uyda kimyoviy tozalashni buyurtma qilish mumkinmi?",answer:"Ha, barcha kerakli jihozlar bilan to'g'ridan-to'g'ri sizning uyingizga kelamiz."},{question:"Matrasdan hayvon hidini olib tashlaysizmi?",answer:"Ha. Hid molekulalarini yo'q qiluvchi ferment neytralizatorlaridan foydalanamiz."}]}},{id:"moyka-okon",img:"/images/moyka-okon.webp",translations:{ru:{title:"Мойка окон в Ташкенте",category:"Фасады и экстерьер",shortDesc:"Профессиональное мытьё окон на любой высоте без разводов.",fullDesc:"Обеспечиваем кристальную чистоту ваших окон. Моем стеклопакеты с обеих сторон, очищаем рамы, подоконники и москитные сетки. Возможна работа на высоких этажах с применением спецснаряжения.",includes:["Мытьё рам и подоконников","Очистка стеклопакетов","Удаление разводов","Работа на высоте"],price:"от 20.000 за 1 Кв М",metaTitle:"Мойка окон в Ташкенте — GrandClean, без разводов",metaDesc:"Профессиональная мойка окон в Ташкенте без разводов. Работа на любой высоте. Цена от 20 000 за м\xb2. ☎ +998 93 571 21 51."},uz:{title:"Oyna yuvish",category:"Fasadlar va tashqi ko'rinish",shortDesc:"Har qanday balandlikda izlarsiz professional oyna yuvish.",fullDesc:"Oynalaringizning kristal tozaligini ta'minlaymiz. Shisha paketlarni ikki tomondan, ramalar, deraza tokchalari va pashshaxonalarni tozalaymiz. Maxsus uskunalar bilan baland qavatlarda ishlash mumkin.",includes:["Rama va deraza tokchasini yuvish","Shisha paketlarni tozalash","Izlarni olib tashlash","Balandda ishlash"],price:"20 000 so'mdan 1 m\xb2 uchun",metaTitle:"Toshkentda oyna yuvish — GrandClean, izsiz",metaDesc:"Toshkentda izsiz professional oyna yuvish. Har qanday balandlikda ishlash. Narx 20 000 so'mdan m\xb2. ☎ +998 93 571 21 51."}},faq:{ru:[{question:"Как часто нужно мыть окна в Ташкенте?",answer:"В условиях ташкентской пыли рекомендуем мыть окна 2–3 раза в год."},{question:"Можете ли вы мыть окна на высоких этажах?",answer:"Да, наши специалисты имеют удостоверения промышленных альпинистов."},{question:"Останутся ли разводы после мытья?",answer:"Нет. Используем дистиллированную воду и профессиональные скребки-сгонки."},{question:"Входит ли уборка подоконников в стоимость?",answer:"Да, в стандартный пакет входит мытьё стёкол, очистка рам, подоконников и москитных сеток."}],uz:[{question:"Toshkentda oynalarni qancha vaqtda bir marta yuvish kerak?",answer:"Toshkent changi sharoitida yiliga 2–3 marta oyna yuvish tavsiya etiladi."},{question:"Baland qavatlarda oyna yuva olasizmi?",answer:"Ha, mutaxassislarimiz sanoat alpinistlari guvohnomasiga ega."},{question:"Yuvishdan keyin izlar qoladimi?",answer:"Yo'q. Distillangan suv va professional squeegeelardan foydalanamiz."},{question:"Deraza tokchasini tozalash narxga kiradimi?",answer:"Ha, standart paketga shisha, rama, deraza tochkasi va pashshaxonani yuvish kiradi."}]}},{id:"mytyo-fasadov",img:"/images/moyka-fasadov.webp",translations:{ru:{title:"Мытьё фасадов в Ташкенте",category:"Фасады и экстерьер",shortDesc:"Очистка фасадов от загрязнений, пыли и копоти.",fullDesc:"Предлагаем услуги промышленного альпинизма для мойки и очистки фасадов коммерческих и жилых зданий. Убираем атмосферные загрязнения, высолы и строительную пыль с любых материалов.",includes:["Очистка стен и облицовки","Удаление копоти и грязи","Промышленное оборудование","Работа на любой высоте"],price:"от 20.000 за 1 Кв М",metaTitle:"Мытьё фасадов зданий в Ташкенте — GrandClean",metaDesc:"Профессиональная очистка фасадов зданий в Ташкенте промышленными альпинистами. Любая высота. Цена от 20 000 за м\xb2. ☎ +998 93 571 21 51."},uz:{title:"Fasadlarni yuvish",category:"Fasadlar va tashqi ko'rinish",shortDesc:"Fasadlarni ifloslanish, chang va qoralik chiqindilaridan tozalash.",fullDesc:"Tijorat va turar-joy binolarining fasadlarini yuvish va tozalash uchun sanoat alpinizmi xizmatlarini ko'rsatamiz.",includes:["Devor va qoplama tozalash","Qoralik va kirni olib tashlash","Sanoat jihozlari","Har qanday balandlikda ishlash"],price:"20 000 so'mdan 1 m\xb2 uchun",metaTitle:"Toshkentda bino fasadlarini yuvish — GrandClean",metaDesc:"Toshkentda sanoat alpinistlari tomonidan professional fasad tozalash. Har qanday balandlik. Narx 20 000 so'mdan m\xb2. ☎ +998 93 571 21 51."}},faq:{ru:[{question:"Как часто нужно мыть фасад здания?",answer:"Для жилых зданий — раз в 2–3 года. Для коммерческих объектов — ежегодно."},{question:"Какие материалы фасадов вы очищаете?",answer:"Работаем с любыми типами: штукатурка, кирпич, бетон, стекло, алюминиевые панели, натуральный камень."},{question:"Нужно ли предупреждать жильцов?",answer:"Мы курируем этот процесс: предупредим о необходимости закрыть окна и согласуем удобное время."},{question:"Безопасна ли химия для окружающей среды?",answer:"Да, все препараты биоразлагаемые и сертифицированы для наружного применения."}],uz:[{question:"Bino fasadini necha yilda bir marta yuvish kerak?",answer:"Turar-joy binolari uchun 2–3 yilda bir marta. Tijorat ob'ektlari uchun har yili."},{question:"Qanday fasad materiallarini tozalaysiz?",answer:"Har qanday turdagi materiallar bilan ishlaymiz: gips, g'isht, beton, shisha, alyuminiy panellar, tabiiy tosh."},{question:"Aholini ogohlantirishga to'g'ri keladimi?",answer:"Ha, biz bu jarayonni nazorat qilamiz: oynalarni yopish zarurligini oldindan aytamiz."},{question:"Kimyo atrof-muhit uchun xavfsizmi?",answer:"Ha, barcha preparatlar biodegradable va tashqi foydalanish uchun sertifikatlangan."}]}},{id:"chistka-bruschatki",img:"/images/chistka-bruschatki.webp",translations:{ru:{title:"Чистка брусчатки в Ташкенте",category:"Фасады и экстерьер",shortDesc:"Удаление мха, грязи и пятен с тротуарной плитки и брусчатки.",fullDesc:"С помощью аппаратов высокого давления (АВД) мы эффективно очищаем дворовые покрытия, брусчатку и бетон от въевшейся грязи, машинного масла, мха и сорняков.",includes:["Удаление мха и грибка","Очистка от грязи","Мойка под давлением","Обработка защитным составом"],price:"от 15.000 сум",metaTitle:"Чистка брусчатки в Ташкенте — GrandClean",metaDesc:"Профессиональная чистка тротуарной плитки и брусчатки аппаратами высокого давления. Удаление мха, масла, грязи. Цена от 15 000 сум. ☎ +998 93 571 21 51."},uz:{title:"Trotuar plitasini tozalash",category:"Fasadlar va tashqi ko'rinish",shortDesc:"Trotuar plitasi va tashlaoqlardan yo'sin, kir va dog'larni olib tashlash.",fullDesc:"Yuqori bosimli apparatlar (YBA) yordamida hovli qoplamalar, trotuar va betonni kirib ketgan kirdan, mashinalar moyidan, yo'sindan tozalaymiz.",includes:["Yo'sin va zamburug'ni olib tashlash","Kirdan tozalash","Bosim ostida yuvish","Himoya tarkibi bilan qayta ishlash"],price:"15 000 so'mdan",metaTitle:"Toshkentda trotuar plitasini tozalash — GrandClean",metaDesc:"Yuqori bosimli apparatlar bilan professional trotuar plitasi va toshloq tozalash. Yo'sin, moy, kirni olib tashlash. Narx 15 000 so'mdan. ☎ +998 93 571 21 51."}},faq:{ru:[{question:"Можно ли чистить брусчатку АВД без повреждений?",answer:"Да, при правильной настройке давления и угла подачи воды."},{question:"Убираете ли вы нефтяные и масляные пятна?",answer:"Да. Предварительно обрабатываем пятна нефтепродуктов обезжиривающим составом, затем смываем АВД."},{question:"Какой защитный состав вы наносите?",answer:"Водоотталкивающую пропитку на акриловой или силиконовой основе на 1–2 года."},{question:"Как быстро можно ходить по брусчатке после очистки?",answer:"Сразу. Если наносился защитный состав — рекомендуем не нагружать поверхность 2–4 часа."}],uz:[{question:"YBA bilan trotuar plitasini zararsiz tozalash mumkinmi?",answer:"Ha, bosim va suvni uzatish burchagini to'g'ri sozlash bilan."},{question:"Neft va moy dog'larini olib tashlaysizmi?",answer:"Ha. Dog'larni avval yog'sizlantiruvchi tarkib bilan ishlab, keyin YBA bilan yuvamiz."},{question:"Qanday himoya tarkibi qo'llaysiz?",answer:"1–2 yilga mo'ljallangan akril yoki silikonli suv itolatuvchi impregnatsiya."},{question:"Tozalashdan keyin trotuar plitasida necha vaqtdan keyin yurish mumkin?",answer:"Darhol. Himoya tarkibi qo'llanilgan bo'lsa, 2–4 soat yuklamaslik tavsiya etiladi."}]}},{id:"dezinfekciya",img:"/images/dezinfekciya.webp",translations:{ru:{title:"Дезинфекция в Ташкенте",category:"Специальные",shortDesc:"Уничтожение бактерий, вирусов и аллергенов. Безопасно для людей.",fullDesc:"Проводим профилактическую и очаговую дезинфекцию помещений методом холодного тумана. Препарат проникает во все щели, гарантированно уничтожая 99.9% патогенной микрофлоры.",includes:["Обработка всех поверхностей","Уничтожение бактерий и вирусов","Генератор холодного тумана","Сертифицированные препараты"],price:"от 500.000 за комнату",metaTitle:"Дезинфекция помещений в Ташкенте — GrandClean",metaDesc:"Профессиональная дезинфекция помещений холодным туманом в Ташкенте. Уничтожение 99.9% бактерий и вирусов. Цена от 500 000. ☎ +998 93 571 21 51."},uz:{title:"Dezinfeksiya",category:"Maxsus",shortDesc:"Bakteriyalar, viruslar va allergenlarni yo'q qilish. Odamlar uchun xavfsiz.",fullDesc:"Sovuq tuman usuli bilan profilaktik va o'choqli dezinfeksiya o'tkazamiz. Preparat barcha teshik va yoriqqa kiradi, 99.9% patogen mikroorganizmlarni kafolatli yo'q qiladi.",includes:["Barcha yuzalarni qayta ishlash","Bakteriya va viruslarni yo'q qilish","Sovuq tuman generatori","Sertifikatlangan preparatlar"],price:"500 000 so'mdan xona uchun",metaTitle:"Toshkentda xonalarni dezinfeksiya qilish — GrandClean",metaDesc:"Toshkentda sovuq tuman bilan professional dezinfeksiya. 99.9% bakteriya va viruslarni yo'q qilish. Narx 500 000 dan. ☎ +998 93 571 21 51."}},faq:{ru:[{question:"Как долго нельзя находиться в помещении после дезинфекции?",answer:"Необходимо проветрить в течение 1–2 часов. Затем помещение полностью безопасно."},{question:"Убивает ли ваша дезинфекция плесень и грибок?",answer:"Да. Используем препараты с фунгицидным действием."},{question:"Нужна ли дезинфекция после болезни в квартире?",answer:"Да, особенно если кто-то переболел вирусной инфекцией."},{question:"Какие документы вы предоставляете после дезинфекции?",answer:"Выдаём акт выполненных работ. Для юрлиц — полный пакет документов."}],uz:[{question:"Dezinfeksiyadan keyin xonada qancha vaqt bo'lmagan ma'qul?",answer:"1–2 soat shamollatish kerak. Keyin xona odamlar uchun mutlaqo xavfsiz."},{question:"Dezinfeksiya mog'or va zamburug'ni o'ldiradi??",answer:"Ha. Fungitsid ta'sirli preparatlardan foydalanamiz."},{question:"Kasallikdan keyin kvartiraga dezinfeksiya kerakmi?",answer:"Ha, ayniqsa uy kishilaridan biri viral infeksiya bilan kasallangan bo'lsa."},{question:"Dezinfeksiyadan keyin qanday hujjatlar berasiz?",answer:"Bajarilgan ishlar dalolatnomasi beriladi. Yuridik shaxslar uchun — to'liq hujjat paketi."}]}},{id:"himchistka-shtor-i-odeyal",img:"/images/hero-interior.webp",translations:{ru:{title:"Химчистка штор, одеял и курпачей в Ташкенте",category:"Специальные",shortDesc:"Безопасное удаление пыли и клещей. Стирка курпачей и химчистка тяжёлых портьер с вывозом или на дому.",fullDesc:"GrandClean выполняет профессиональную химчистку штор, занавесок, одеял и курпачей в Ташкенте. Мы безопасно удаляем пыль, пылевых клещей и аллергены, возвращая текстилю свежесть и мягкость. Тяжёлые портьеры чистим на дому или с бесплатным вывозом в цех — подберём удобный формат для вашей квартиры или дома.",includes:["Химчистка штор и занавесок","Стирка и чистка курпачей","Чистка одеял и подушек","Вывоз тяжёлых портьер или работа на дому","Удаление пыли и пылевых клещей","Деликатная сушка и дезодорация"],advantages:[{title:"Стирка курпачей в Ташкенте без повреждений",description:"Бережно обрабатываем курпачи из хлопка, бязи и смесовых тканей: удаляем загрязнения, сохраняя форму и насыщенность цвета."},{title:"Безопасное удаление пыли и клещей",description:"Используем сертифицированные гипоаллергенные средства и паровую обработку для уничтожения пылевых клещей и аллергенов."},{title:"Химчистка тяжёлых портьер с вывозом",description:"Забираем объёмные портьеры в цех, выполняем глубокую чистку и возвращаем готовый текстиль — без риска для вашего интерьера."},{title:"Чистка на дому без демонтажа",description:"Для лёгких штор и занавесок приезжаем с портативным оборудованием и проводим химчистку прямо у вас."}],price:"от 35.000 сум",metaTitle:"Химчистка штор, одеял и курпачей в Ташкенте — GrandClean",metaDesc:"Химчистка штор, занавесок, одеял и курпачей в Ташкенте. Безопасное удаление пыли и клещей, стирка курпачей, чистка тяжёлых портьер с вывозом. ☎ +998 93 571 21 51."},uz:{title:"Toshkentda parda, ko'rpa va kurpachalarni kimyoviy tozalash",category:"Maxsus",shortDesc:"Chang va chang kanalarini xavfsiz yo'q qilish. Kurpachalarni yuvish va og'ir pardalarni uyda yoki olib ketish bilan tozalash.",fullDesc:"GrandClean Toshkentda parda, jalyuzi, ko'rpa va kurpachalarni professional kimyoviy tozalash xizmatini ko'rsatadi. Chang, chang kanalari va allergenlarni xavfsiz yo'q qilamiz. Og'ir pardalarni uyda yoki bepul olib ketish bilan sexda tozalaymiz.",includes:["Parda va jalyuzilarni kimyoviy tozalash","Kurpachalarni yuvish va tozalash","Ko'rpa va yostiqchalarni tozalash","Og'ir pardalarni olib ketish yoki uyda ishlash","Chang va chang kanalarini yo'q qilish","Nozik quritish va deodoratsiya"],advantages:[{title:"Toshkentda kurpachalarni zararsiz yuvish",description:"Paxta, mata va aralash matodan tayyorlangan kurpachalarni ehtiyotkorlik bilan tozalaymiz: ifloslanishni olib tashlab, shakl va rangni saqlaymiz."},{title:"Chang va chang kanalarini xavfsiz yo'q qilish",description:"Chang kanalari va allergenlarni yo'q qilish uchun sertifikatlangan gipoallergen vositalar va bug' bilan ishlaymiz."},{title:"Og'ir pardalarni olib ketish bilan tozalash",description:"Katta hajmli pardalarni sexga olib ketamiz, chuqur tozalash qilamiz va tayyor matoni qaytaramiz."},{title:"Uyda demontajsiz tozalash",description:"Yengil parda va jalyuzilar uchun portativ uskunalar bilan to'g'ridan-to'g'ri uyga kelamiz."}],price:"35 000 so'mdan",metaTitle:"Toshkentda parda, ko'rpa va kurpachalarni kimyoviy tozalash — GrandClean",metaDesc:"Toshkentda parda, ko'rpa va kurpachalarni kimyoviy tozalash. Chang va chang kanalarini xavfsiz yo'q qilish, kurpachalarni yuvish. ☎ +998 93 571 21 51."}},faq:{ru:[{question:"Как часто нужно чистить курпачи и одеяла в Ташкенте?",answer:"Рекомендуем профессиональную чистку курпачей и одеял 1–2 раза в год, особенно в сезон цветения и при аллергии у детей."},{question:"Можно ли заказать химчистку штор без снятия с карниза?",answer:"Да, для лёгких тканей проводим чистку на месте. Тяжёлые портьеры надёжнее обрабатывать с вывозом в цех."},{question:"Удаляете ли вы пылевых клещей из одеял и подушек?",answer:"Да, используем паровую обработку и антиаллергенные составы, которые уничтожают клещей и нейтрализуют аллергены."},{question:"Сколько сохнут курпачи после стирки?",answer:"При профессиональной сушке в цехе — 24–48 часов. На дому срок зависит от толщины ткани и вентиляции помещения."}],uz:[{question:"Toshkentda kurpacha va ko'rpalarni qancha vaqtda bir tozalash kerak?",answer:"Kurpacha va ko'rpalarni yiliga 1–2 marta professional tozalash tavsiya etiladi, ayniqsa gullash mavsumida va bolalarda allergiya bo'lsa."},{question:"Pardalarni karnizdan yechmasdan tozalash mumkinmi?",answer:"Ha, yengil matolar uchun joyida tozalash mumkin. Og'ir pardalar sexda ishlash xavfsizroq."},{question:"Ko'rpa va yostiqchalardan chang kanalarini olib tashlaysizmi?",answer:"Ha, bug' bilan ishlov va antiallergen tarkiblar chang kanalarini yo'q qiladi va allergenlarni neytrallashtiradi."},{question:"Yuvishdan keyin kurpachalar qancha qurishadi?",answer:"Sexda professional quritishda — 24–48 soat. Uyda mato qalinligi va shamollatishga bog'liq."}]}},{id:"himchistka-detskih-kolyasok",img:"/images/baby-stroller-cleaning.webp",translations:{ru:{title:"Химчистка детских колясок в Ташкенте",category:"Специальные",shortDesc:"Химчистка детских автокресел, удаление пятен от еды и соков. Гипоаллергенные эко-средства, безопасные для детей 0+.",fullDesc:"Профессиональная химчистка детских колясок, люлек и автокресел в Ташкенте. Удаляем пятна от еды, соков, молока и следы активных игр. Используем только гипоаллергенные эко-средства, сертифицированные для детей 0+, без резкого запаха и токсичных остатков.",includes:["Химчистка колясок и люлек","Чистка детских автокресел","Удаление пятен от еды и соков","Обработка ремней и мягких вставок","Дезинфекция и нейтрализация запахов","Безопасные эко-средства для детей 0+"],advantages:[{title:"Химчистка детских автокресел в Ташкенте",description:"Глубоко очищаем обивку и ремни автокресел, не нарушая защитные свойства материалов и креплений."},{title:"Удаление пятен от еды и соков",description:"Выводим следы фруктовых соков, пюре, молока и других детских загрязнений без разводов и пятен."},{title:"Гипоаллергенные эко-средства для детей 0+",description:"Применяем только сертифицированную химию без агрессивных компонентов — безопасно для новорождённых и малышей."},{title:"Дезинфекция без вредных остатков",description:"Уничтожаем бактерии и неприятные запахи, оставляя коляску свежей и готовой к использованию в тот же день."}],price:"от 80.000 сум",metaTitle:"Химчистка детских колясок и автокресел в Ташкенте — GrandClean",metaDesc:"Химчистка детских колясок, люлек и автокресел в Ташкенте. Удаление пятен от еды и соков, гипоаллергенные эко-средства для детей 0+. ☎ +998 93 571 21 51."},uz:{title:"Toshkentda bolalar aravachalarini kimyoviy tozalash",category:"Maxsus",shortDesc:"Bolalar avtokreslolarini kimyoviy tozalash, ovqat va sharbat dog'larini olib tashlash. 0+ bolalar uchun xavfsiz gipoallergen eko-vositalar.",fullDesc:"Toshkentda bolalar aravachalari, beshiklar va avtokreslolarini professional kimyoviy tozalash. Ovqat, sharbat, sut dog'lari va faol o'yin izlarini olib tashlaymiz. Faqat 0+ bolalar uchun sertifikatlangan gipoallergen eko-vositalardan foydalanamiz.",includes:["Aravacha va beshiklarni kimyoviy tozalash","Bolalar avtokreslolarini tozalash","Ovqat va sharbat dog'larini olib tashlash","Tasmalar va yumshoq qismlarni ishlov berish","Dezinfeksiya va hidni neytrallashtirish","0+ bolalar uchun xavfsiz eko-vositalar"],advantages:[{title:"Toshkentda bolalar avtokreslolarini tozalash",description:"Avtokreslo matosi va tasmalarini chuqur tozalaymiz, himoya xususiyatlari va mahkamlashlarni buzmasdan."},{title:"Ovqat va sharbat dog'larini olib tashlash",description:"Meva sharbatlari, pyure, sut va boshqa bolalar ifloslanishlarini iz va dog'siz olib tashlaymiz."},{title:"0+ bolalar uchun gipoallergen eko-vositalar",description:"Faqat sertifikatlangan, agressiv komponentlarsiz kimyo — yangi tug'ilgan chaqaloqlar va bolajonlar uchun xavfsiz."},{title:"Zararli qoldiqlarsiz dezinfeksiya",description:"Bakteriyalar va yoqimsiz hidlarni yo'q qilamiz, aravachani shu kunning o'zida foydalanishga tayyor qoldiramiz."}],price:"80 000 so'mdan",metaTitle:"Toshkentda bolalar aravachalari va avtokreslolarini tozalash — GrandClean",metaDesc:"Toshkentda bolalar aravachalari, beshiklar va avtokreslolarini kimyoviy tozalash. Ovqat dog'lari, 0+ uchun xavfsiz eko-vositalar. ☎ +998 93 571 21 51."}},faq:{ru:[{question:"Безопасна ли химчистка коляски для новорождённого?",answer:"Да, мы используем только гипоаллергенные эко-средства, сертифицированные для детей 0+, без агрессивных отдушек и токсичных остатков."},{question:"Удаляете ли вы пятна от соков и детского питания?",answer:"Да, ферментные составы эффективно расщепляют пятна от фруктовых соков, пюре, молока и других продуктов."},{question:"Сколько сохнет коляска после химчистки?",answer:"В среднем 4–8 часов при комнатной температуре. Мы используем экстрактор, который вытягивает влагу из обивки."},{question:"Чистите ли вы люльки и прогулочные блоки отдельно?",answer:"Да, обрабатываем люльки, прогулочные коляски и детские автокресла — как комплексно, так и по отдельности."}],uz:[{question:"Yangi tug'ilgan chaqaloq uchun aravachani tozalash xavfsizmi?",answer:"Ha, faqat 0+ bolalar uchun sertifikatlangan gipoallergen eko-vositalardan foydalanamiz, agressiv hidlar va toksik qoldiqlarsiz."},{question:"Sharbat va bolalar ovqati dog'larini olib tashlaysizmi?",answer:"Ha, ferment tarkiblar meva sharbatlari, pyure, sut va boshqa mahsulot dog'larini samarali parchalaydi."},{question:"Kimyoviy tozalashdan keyin aravacha qancha qurishadi?",answer:"Xona haroratida o'rtacha 4–8 soat. Matodan namlikni chiqarib oladigan ekstraktor ishlatamiz."},{question:"Beshik va yurish bloklarini alohida tozalaysizmi?",answer:"Ha, beshiklar, yurish aravachalari va bolalar avtokreslolarini kompleks yoki alohida ishlaymiz."}]}}];function n(a,i){return a.translations[i]??a.translations.ru}},8464:(a,i,s)=>{s.d(i,{P:()=>n,W:()=>l});let l="https://grandclean.uz",n={name:"GrandClean",alternateName:"Гранд Клин",phoneE164:"+998935712151",phoneDisplay:"+998 (93) 571-21-51",email:"info@grandclean.uz",priceRange:"$$",foundingDate:"2019",workHours:"Mo-Su 08:00-22:00",workHoursDisplay:"Пн-Вс: 08:00 — 22:00",address:{streetAddress:"ул. Жураева, 48",addressLocality:"Ташкент",addressRegion:"Ташкент",postalCode:"100000",addressCountry:"UZ"},geo:{lat:"41.281918",lng:"69.254747"},sameAs:["https://t.me/grandclean_uz","https://www.instagram.com/grandcleanuz/","https://www.facebook.com/profile.php?id=100092282247198"]}}};